import re
lines=open('prog.pw9').read().splitlines()
prog=[]
for ln in lines:
    s=ln.split(';')[0].strip()
    if s: prog.append(s.split())
regs={'a':0,'b':0,'c':0,'d':0}
def val(x):
    return regs[x] if x in regs else int(x)
pc=0; count=0; out=[]
while 0<=pc<len(prog):
    ins=prog[pc]; op=ins[0]; count+=1
    if op=='set':
        regs[ins[1]]=val(ins[2])%65536
    elif op=='add':
        regs[ins[1]]=(regs[ins[1]]+val(ins[2]))%65536
    elif op=='mul':
        regs[ins[1]]=(regs[ins[1]]*val(ins[2]))%65536
    elif op=='mod':
        x=val(ins[2])
        if x>0: regs[ins[1]]%=x
    elif op=='dec':
        regs[ins[1]]=max(0,regs[ins[1]]-1)
    elif op=='jnz':
        if val(ins[1])!=0:
            pc+=val(ins[2]); continue
    elif op=='skp':
        if val(ins[1])<val(ins[2]):
            pc+=2; continue
    elif op=='out':
        out.append(val(ins[1]))
    pc+=1
print(sum(out), count, len(out))
print(out)
EOF
