const fs=require('fs');
let src=fs.readFileSync('prog.pw9','utf8');
let prog=src.split('\n').map(l=>l.split(';')[0].trim()).filter(Boolean).map(l=>l.split(/\s+/));
let R={a:0,b:0,c:0,d:0};
const V=x=>/^-?\d+$/.test(x)?parseInt(x,10):R[x];
const M=65536;
let pc=0,n=0,sum=0,outs=[],iters=0,skips=0;
while(pc>=0&&pc<prog.length){
  const [op,r,x]=prog[pc]; n++;
  if(op==='set')R[r]=((V(x)%M)+M)%M;
  else if(op==='add')R[r]=(((R[r]+V(x))%M)+M)%M;
  else if(op==='mul')R[r]=((R[r]*V(x)%M)+M)%M;
  else if(op==='mod'){const y=V(x); if(y>0)R[r]=R[r]%y;}
  else if(op==='dec')R[r]=Math.max(0,R[r]-1);
  else if(op==='jnz'){if(V(r)!==0){pc+=V(x);continue;}}
  else if(op==='skp'){if(V(r)<V(x)){pc+=2;skips++;continue;}}
  else if(op==='out'){outs.push(V(r));sum+=V(r);}
  pc++;
}
console.log(JSON.stringify({sum,n,count:outs.length,R,skips,last:outs.slice(-5)}));
EOF
